package com.medicalaid.app.content

object Conditions {
    val pregnancy: List<Condition> = PregnancyConditions.all + ChronicConditions.pregnancy
    val general: List<Condition> = ChronicConditions.general + cardioRenalConditions + heartConditions + substanceConditions
    /**
     * Infections A–Z: the user's Gemini drafts, compiled as written (not independently reviewed — see README).
     * Generated by .claude-work/infections/convert.py; sorted A–Z by title.
     */
    val infections: List<Condition> = (infectionsACConditions + infectionsDHConditions + infectionsHLConditions +
        infectionsLRConditions + infectionsSZConditions).sortedBy { it.title.lowercase() }
    val infectionSources: List<Source> =
        infectionsACSources + infectionsDHSources + infectionsHLSources + infectionsLRSources + infectionsSZSources
    val all: List<Condition> = pregnancy + general + infections

    private val index = all.associateBy { it.id }

    fun byId(id: String): Condition? = index[id]

    fun of(population: Population) = when (population) {
        Population.Pregnancy -> pregnancy
        Population.General -> general
        Population.Infections -> infections
    }
}
